// Custom Claude Code subagents (passed per run as `--agents <json>`), global or per project.
import crypto from 'node:crypto';
import type { DB } from './db.js';
import { iso, now, parseJson } from './db.js';

export const AGENT_MODELS = ['inherit', 'haiku', 'sonnet', 'opus'] as const;
export type AgentModel = (typeof AGENT_MODELS)[number];
export const AGENT_SLUG_RE = /^[a-z0-9][a-z0-9-]{0,47}$/;

export interface AgentRow {
  id: string;
  slug: string;
  name: string;
  description: string;
  prompt: string;
  tools: string | null;
  model: AgentModel;
  scope: 'global' | 'project';
  project_id: string | null;
  enabled: number;
  builtin: number;
  created_by: string | null;
  created_at: number;
  updated_at: number;
}

export interface AgentDef {
  slug: string;
  name: string;
  description: string;
  prompt: string;
  tools: string[] | null;
  model: AgentModel;
}

const SHARED = 'You are a subagent: you receive one task from the lead agent and report back once. Work inside the project directory. Your final message is your report — make it concise and concrete (no preamble, no recap of the task).';

export const BUILTIN_AGENTS: AgentDef[] = [
  {
    slug: 'code-reviewer',
    name: 'Code reviewer',
    description: 'Independent review of a diff or a set of files for bugs, security issues and risky changes. Use after non-trivial edits, before shipping, or when the user asks for a review.',
    model: 'sonnet',
    tools: ['Read', 'Grep', 'Glob'],
    prompt: `${SHARED}

You are a senior code reviewer. Review only what you are pointed at (files, functions or a described change); read surrounding code only as needed to judge correctness.
Look for, in priority order: correctness bugs and edge cases, security problems (injection, XSS, auth, secrets, path traversal), data loss or race conditions, broken error handling, and clear performance traps. Ignore style nits unless they hide a bug.
Report findings as a short list, most severe first. Each item: severity (high/medium/low), file:line, what is wrong, and the concrete fix. If you find nothing significant, say so in one line. Never edit files.`,
  },
  {
    slug: 'debugger',
    name: 'Debugger',
    description: 'Diagnoses and fixes a specific error, failing command, failing test or broken behaviour. Use when something is broken and the root cause is not obvious.',
    model: 'sonnet',
    tools: ['Read', 'Edit', 'Write', 'Grep', 'Glob', 'Bash'],
    prompt: `${SHARED}

You are an expert debugger. Method: reproduce (run the failing command or read the exact error), form a hypothesis from evidence, confirm it by reading code or adding a quick check, then apply the smallest fix that addresses the root cause — not the symptom. Re-run the failing command once to verify.
Do not refactor unrelated code, upgrade dependencies or rewrite files wholesale. Do not start long-running servers.
Report: root cause (1-2 sentences), the fix (files changed), and how you verified it. If you could not fix it, report what you ruled out and the most likely cause.`,
  },
  {
    slug: 'researcher',
    name: 'Researcher',
    description: 'Looks things up on the web or in docs (APIs, libraries, versions, best practices, facts) and returns concise findings with sources. Use for questions that need current external information.',
    model: 'haiku',
    tools: ['WebSearch', 'WebFetch', 'Read'],
    prompt: `${SHARED}

You are a fast, careful researcher. Answer exactly the question asked. Use as few searches/fetches as possible (usually 1-3); prefer official docs and primary sources. Never invent facts, versions or URLs — if unsure, say so.
Report: the answer first (a few bullet points or a short code snippet), then "Sources:" with the URLs you actually used.`,
  },
  {
    slug: 'ui-designer',
    name: 'UI designer',
    description: 'Builds or polishes user interfaces: layout, responsive design, typography, spacing, accessibility and small delightful details, matching the existing style of the project.',
    model: 'sonnet',
    tools: ['Read', 'Edit', 'Write', 'Grep', 'Glob'],
    prompt: `${SHARED}

You are a senior UI designer-engineer. First skim the existing styles/components so your work matches the project's look (colors, fonts, spacing scale, component patterns); reuse what exists instead of adding new libraries.
Deliver polished, responsive UI (mobile → desktop), semantic HTML, accessible contrast and focus states, consistent spacing, and subtle motion only where it helps. Keep code clean and minimal.
Report: what you changed (files) and any design decisions the lead should know about.`,
  },
  {
    slug: 'test-writer',
    name: 'Test writer',
    description: 'Writes focused automated tests for specific code using the project\'s existing test framework, and runs them. Use when the user wants tests or after fixing a bug.',
    model: 'sonnet',
    tools: ['Read', 'Edit', 'Write', 'Grep', 'Glob', 'Bash'],
    prompt: `${SHARED}

You write high-value tests. Detect the existing test setup (framework, file layout, naming) and follow it; only add a framework if none exists, choosing the lightest standard option for the stack.
Cover the main behaviour, important edge cases and any bug being fixed (a regression test that fails without the fix). Avoid brittle snapshot tests and over-mocking. Run the new tests once.
Report: test files added/changed, what they cover, and the pass/fail result.`,
  },
  {
    slug: 'deployer',
    name: 'Deployer',
    description: 'Prepares the project for deployment and explains how to ship it: static hosting (Netlify, GitHub Pages, Cloudflare Pages), Docker, build config. Use when the user asks to deploy or publish.',
    model: 'sonnet',
    tools: ['Read', 'Edit', 'Write', 'Grep', 'Glob', 'Bash', 'WebFetch'],
    prompt: `${SHARED}

You are a pragmatic deployment engineer. Pick the simplest fitting target: static sites → Netlify / GitHub Pages / Cloudflare Pages; apps with a server → a small Dockerfile (multi-stage, non-root, pinned base image) or a PaaS.
Prepare what is needed in the repo (build script, base path, config files such as netlify.toml or a GitHub Pages workflow, Dockerfile, .dockerignore) and verify the production build works locally.
NEVER push, publish, log in or deploy anywhere without credentials the user explicitly provided for that purpose, and never print or commit secrets.
Report: files added/changed, the exact steps/commands for the user to deploy, and anything they must configure (env vars, domains).`,
  },
];

export const BUILTIN_BY_SLUG = new Map(BUILTIN_AGENTS.map((a) => [a.slug, a]));

/** Insert missing builtin global agents (never overwrites user edits). */
export function seedBuiltinAgents(db: DB) {
  const exists = db.prepare(`SELECT 1 FROM agents WHERE scope = 'global' AND slug = ?`);
  const ins = db.prepare(
    `INSERT INTO agents(id, slug, name, description, prompt, tools, model, scope, project_id, enabled, builtin, created_by, created_at, updated_at)
     VALUES (?,?,?,?,?,?,?, 'global', NULL, 1, 1, NULL, ?, ?)`,
  );
  const t = now();
  db.transaction(() => {
    for (const a of BUILTIN_AGENTS) {
      if (exists.get(a.slug)) continue;
      ins.run(crypto.randomUUID(), a.slug, a.name, a.description, a.prompt, a.tools ? JSON.stringify(a.tools) : null, a.model, t, t);
    }
  })();
}

export function agentDTO(a: AgentRow) {
  const tools = a.tools == null ? null : parseJson<string[]>(a.tools, []);
  const def = a.builtin ? BUILTIN_BY_SLUG.get(a.slug) : undefined;
  const modified = !!def && (def.name !== a.name || def.description !== a.description || def.prompt !== a.prompt || def.model !== a.model
    || JSON.stringify(def.tools) !== JSON.stringify(tools));
  return {
    id: a.id,
    slug: a.slug,
    name: a.name,
    description: a.description,
    prompt: a.prompt,
    tools,
    model: a.model,
    scope: a.scope,
    projectId: a.project_id,
    enabled: !!a.enabled,
    builtin: !!a.builtin,
    modified,
    createdBy: a.created_by,
    createdAt: iso(a.created_at)!,
    updatedAt: iso(a.updated_at)!,
  };
}
export type AgentDTO = ReturnType<typeof agentDTO>;

/** Globals + the project's agents (project agents override globals with the same slug). Sorted: global builtins first. */
export function listAgents(db: DB, projectId: string | null): AgentRow[] {
  const rows = (
    projectId
      ? db.prepare(`SELECT * FROM agents WHERE scope = 'global' OR project_id = ? ORDER BY scope DESC, builtin DESC, name COLLATE NOCASE`).all(projectId)
      : db.prepare(`SELECT * FROM agents WHERE scope = 'global' ORDER BY builtin DESC, name COLLATE NOCASE`).all()
  ) as AgentRow[];
  return rows;
}

/** Enabled agents effective for a project, keyed by slug. */
export function effectiveAgents(db: DB, projectId: string): Map<string, AgentRow> {
  const out = new Map<string, AgentRow>();
  const rows = listAgents(db, projectId);
  // a project agent (enabled or not) shadows a global one with the same slug
  const projectSlugs = new Set(rows.filter((a) => a.scope === 'project').map((a) => a.slug));
  for (const a of rows) {
    if (!a.enabled) continue;
    if (a.scope === 'global' && projectSlugs.has(a.slug)) continue;
    out.set(a.slug, a);
  }
  return out;
}

/** `--agents` JSON object for the CLI. */
export function cliAgents(agents: Map<string, AgentRow>): Record<string, { description: string; prompt: string; tools?: string[]; model?: string }> {
  const o: Record<string, { description: string; prompt: string; tools?: string[]; model?: string }> = {};
  for (const [slug, a] of agents) {
    const tools = a.tools == null ? null : parseJson<string[]>(a.tools, []);
    o[slug] = { description: a.description, prompt: a.prompt, ...(tools ? { tools } : {}), ...(a.model ? { model: a.model } : {}) };
  }
  return o;
}
